    this.evalDimDepth = 0;
    this.inPopulateEnvDepth = 0;
    this.evalConstPkgDepth = 0;
    this.errorCode = 0;
    this.errorStartByte = 0xffffffff;
    this.errorEndByte = 0xffffffff;
    this.curEqLoc = 0;
    this.curEqDescId = 0xffffffff;
    this.debugVal1 = 0;
