export function flattener_setExprLeft(daePtr: u32, exprId: u32, leftVal: u32): void {
  if (daePtr == 0) return;
  let d = changetype<DaeBuilder>(daePtr);
  if (exprId >= d.exprCount) return;
  ExprAccessor.at(d.getExprData(), exprId).left = leftVal;
}

